package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaHaDraft4 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_rooster_donkey" to DuaText("Jin Zakara ko Jaki", "Ya Allah ina rokonka falalarka ( zakara). - Ina neman tsarin Allah daga Shaidan La'ananne (Jaki).", "Idan ya ji zakara ya roki falalar Allah; da jin kurin jaki ya nemi tsari daga Shaidan.", "Zakara yaga mala'ika jaki kuma yaga shaidan."),
        "dua_something_liked" to DuaText("Ganin Wani Abu Abin Sha'awa (Against Evil Eye)", "Abin da Allah Ya so. Ya Allah kayi albarka.", "Idan ka ga wani abu mai ban sha'awa na wani, yi addu'a don albarka.", "Addu'ar albarka yana hana mugun ido."),
        "dua_sell_buy_debt_repaid" to DuaText("Lokacin Biyan Bashi", "Allah ya saka muku da gidan Aljanna da dukiyoyin ku.", "Ga mai ba da bashi lokacin biyan bashi.", "Komawar rance shine godiya da biya."),
        "dua_talbiyah" to DuaText("Talbiyah", "Ina nan, Ya Allah, ga ni nan. Ga ni, Ba ku da abokin tarayya, ga ni. Lallai dukkan yabo da albarka da mulki naka ne. Ba ku da abokin tarayya.", "Kaga bayan shigar ihrami.", "Alamar Hajji da Umrah."),
        "dua_yamani_hajar" to DuaText("Tsakanin Rukn Yamani da Hajar Aswad", "Ya Ubangijinmu ka bamu mai kyau a duniya da mai kyau a lahira, kuma ka kare mu daga azabar wuta.", "A cikin tawaf, tsakanin Kusurwar Yaman da Baƙar Dutse.", "Annabi ﷺ ya karanta wannan a wannan wuri cikin tawafi."),
        "dua_safa_marwa" to DuaText("A Safa da Marwah", "Babu abin bautawa da gaskiya sai Allah, Shi kadai, ba tare da abokin tarayya ba. Nasa ne mulki kuma gõdiya ta tabbata, kuma Shĩ, a kan kõme, Mai ĩkon yi ne. Babu abin bautawa da gaskiya sai Allah Shi kadai. Ya cika alkawarinsa, ya taimaki bawansa kuma shi kadai ya karya }ungiyoyin }ungiyoyi.", "Hawan Safa da fuskantar alqibla (sau uku).", "Zikirin Annabi ﷺ akan Safa da Marwah."),
        "dua_arafah" to DuaText("Mafi kyawun Addu'ar Ranar Arafah", "Babu abin bautawa da gaskiya sai Allah, Shi kadai, ba tare da abokin tarayya ba. Nasa ne mulki kuma gõdiya ta tabbata, kuma Shĩ, a kan kõme, Mai ĩkon yi ne.", "Ranar Arafah - mafi kyawun addu'a.", "Mafificiyar addu'a ita ce addu'ar ranar Arafah, kuma mafifitan kalmomi sune wadannan."),
        "dua_takbeer_tashreeq" to DuaText("Takbier-e-Tashreeq", "Allahu akbar, Allah shine mafi girma. Bãbu abin bautãwa fãce Allah. Allah ne mafi girma, Allah ne Mafi girma, kuma dukkan godiya ta tabbata ga Allah.", "Bayan kowace sallar farilla daga ranar 9 ga watan Zul-Hijja zuwa ranar 13 ga watan Zul-Hijjah.", "An ruwaito daga Ali da Ibn Mas’ud (RA) — wajib a cewar Hanafiyya."),
        "dua_zamzam" to DuaText("Shan Zamzam", "Ya Allah ina rokonka ilimi mai amfani, yalwataccen arziki da waraka daga kowace cuta.", "Lokacin shan Zamzam, yi dua ga duk abin da kuke so.", "Zamzam na duk abin da aka sha shi ne (Ibn Majah 3062)."),
        "dua_q_ma_khalaqta_batila" to DuaText("Tunani akan Halitta", "Ya Ubangijinmu, ba ka halicci wannan duka a banza ba. Tsarki ya tabbata gareka, don haka ka tsare mu daga azabar wuta.", "Addu'ar masu tunani a kan halittar sammai da ƙasa.", "Addu'ar masu hankali (ulul-albab)."),
        "dua_q_sami_na_munadiyan" to DuaText("Mun Ji Mai Kira zuwa ga Imani", "Ubangijinmu, mun ji wani mai kira yana kira zuwa ga imani, yana cewa: ‘Ku yi imani da Ubangijinku’, kuma muka yi imani. Ya Ubangijinmu Ka gafarta mana zunubanmu, Ka kankare mana munanan ayyukanmu, kuma Ka kashe mu tare da salihai.", "Addu'a don imani da mutuwa a cikin salihai.", "Addu'ar gafara da kyakkyawan karshe."),
        "dua_q_atina_ma_waadtana" to DuaText("Ka Bamu Abinda Kayi Alkawari", "Ya Ubangijinmu Ka ba mu abin da Ka yi mana wa'adi ta hanyar ManzanninKa, kuma kada ka tozarta mu a Ranar Kiyama. Lalle ne Kai, bã ka warware alkawari.", "Ku gudu daga wulãkanci a Rãnar ¡iyãma.", "Neman daraja a Lahira."),
        "dua_q_israfana" to DuaText("Ka gafarta Mamu", "Ubangijinmu, Ka gãfarta mana zunubanmu da ƙetarewarmu a cikin al'amarinmu. Ka tabbatar da ƙafãfunmu, kuma Ka taimake mu a kan mutãnen nan kãfirai.", "Addu'ar Sahabban Annabawan farko.", "Addu'ar juriya da gafara."),
        "dua_q_jamiun_nas" to DuaText("Zaka Tara Dan Adam", "Ya Ubangijinmu! Lalle ne Kai, kanã tãra mutãne a wani yini wanda bãbu shakka a cikinsa. Lalle ne Allah bã Ya warware alkawarinSa.", "Mai tabbatar da yaqini a Ranar Alqiyamah.", "Addu'ar masu tsayuwa a kan ilimi."),
        "dua_q_maash_shahidin" to DuaText("Ka Rubuto Mu Cikin Shaidu", "Ubangijinmu, mun yi imani, saboda haka ka rubuta mu a cikin masu shaida.", "Addu'ar wadanda suka gane gaskiya kuma suka yi imani.", "Addu'a don karbuwar imani."),
        "dua_q_la_tajalna_zalimin" to DuaText("Ba Tare da Azzalumai ba", "Ya Ubangijinmu kada Ka sanya mu a cikin mutane azzalumai.", "Addu'ar mutanen al-A'araf.", "Ku mafaka daga makomar azzalumai."),
        "dua_q_tawaffana_muslimin" to DuaText("Hakuri da Rasuwa a matsayin Musulmi", "Ya Ubangijinmu Ka Zuba Mana Hakuri Ka Kashe Mu Muna Musulmai.", "Addu'ar masihirtan Fir'auna a lokacin da suka yi imani.", "Hakuri a cikin jarrabawa da qarshen imani."),
        "dua_q_la_tajalna_fitnah" to DuaText("Ba fitina Ga Azzalumai ba", "Ga Allah muka dogara. Ya Ubangijinmu kada Ka sanya mu fitina ga mutane azzalumai, kuma Ka tsare mu da rahamarKa daga mutane kafirai.", "Addu'ar mutanen Musa (AS).", "Addu'ar kubuta daga zalunci da azzalumai."),
        "dua_q_nuh_ma_laysa_li" to DuaText("Addu'ar Nuhu (AS) don Gafara", "Ya Ubangijina, ina neman tsarinka da in roƙe ka abin da ba ni da ilmi game da shi. Kuma idan ba Ka gãfarta mini ba, kuma Ka yi mani rahama, to, zan kasance daga mãsu hasãra.", "Addu'ar tubar Annabi Nuhu (AS).", "Darasi a cikin tambaya tare da kyawawan halaye."),
        "dua_q_mudkhala_sidq" to DuaText("Shiga da Fitar Gaskiya", "Ubangijina, Ka shigar da ni da gaskiya, kuma in fita da gaskiya. Kuma Ka bã ni wani dalĩli mai taimako daga gunKa.", "Kafin shigar da sabon ɗawainiya, gida ko wuri.", "Addu'ar da aka karantar da Annabi ﷺ a lokacin Hijira."),
        "dua_q_la_tadharni_fardan" to DuaText("Dua of Zakariya (AS) - Kar Ka Bar Ni Ni kaɗai", "Ubangijina kada ka bar ni ni kadai, kuma Kai ne Mafi alherin magada.", "Ga masu neman yara.", "Da wannan addu'ar Allah ya ba Yahaya (AS)."),
        "dua_q_munzalan_mubarakan" to DuaText("Wuri Mai Albarka", "Ya Ubangiji ka ba ni kasa a wuri mai albarka, kuma kai ne mafi alherin masu kawo kasa.", "Lokacin ƙaura zuwa sabon gida ko tsayawa wani wuri - dua na Nuhu (AS).", "Addu'a don albarka a sabon wuri."),
        "dua_q_amanna_faghfir" to DuaText("Mun yi Imani, Saboda haka Ka gafarta mana", "Ya Ubangijinmu, mun yi imani, saboda haka Ka gafarta mana, kuma Ka yi mana rahama, kuma Kai ne Mafi alherin masu rahama.", "Addu'ar bayin Allah salihai.", "Cikakken addu'a don gafara da rahama."),
        "dua_q_isrif_jahannam" to DuaText("Ka nisanci azabar wuta", "Ubangijinmu! Ka karkatar da mu daga azabar Jahannama. Lalle ne azãbarta yã kasance mai ɗaure. Lalle ne ita tir da mazauni da mazauni.", "Addu'ar bayin mai rahama ('Ibad ar-Rahman).", "Addu'ar Alqur'ani don neman tsari daga wuta."),
        "dua_q_hab_li_hukman" to DuaText("Addu'ar Ibrahim (AS) - Hikima da Jannah", "Ya Ubangijina, Ka ba ni hikima, kuma Ka riskar da ni da salihai, Ka ba ni ambato mai girma a cikin mutanen qarshe, kuma Ka sanya ni cikin magada Aljannar ni'ima.", "Neman hikima, jama'ar salihai da Aljannah.", "Addu'ar Ibrahim (AS)."),
        "dua_q_lut_najjini_ahli" to DuaText("Dua na Lutu (AS) - Cece Iyalina", "Ubangijĩna Ka tsĩrar da ni da mutãnena daga abin da suke aikatãwa.", "Kare iyali daga muhallin sharri.", "Kariyar iyali daga sharri."),
        "dua_q_sulaiman_awzini" to DuaText("Addu'ar Sulaiman (AS) Domin Godiya", "Ubangijina Ka ba ni ikon gode wa ni’imarKa wadda Ka yi min ni da mahaifana, da aikata ayyukan qwarai da suka yarda da kai, kuma Ka shigar da ni da rahamarKa a cikin bayinka salihai.", "Domin ikon yin godiya ga albarka.", "Addu'ar godiya Sulaiman (AS)."),
        "dua_q_musa_zalamtu" to DuaText("Dua of Musa (AS) - Na yi kuskure", "Ya Ubangijina, na zalunci kaina, don haka Ka gafarta mini.", "Tuba kai tsaye bayan kuskure.", "Allah ya gafartawa Musa (AS)."),
        "dua_q_musa_najjini" to DuaText("Addu'ar Musa (AS) - Ka cece ni daga azzalumai", "Ya Ubangijina, Ka tsĩrar da ni daga mutãne azzãlumai.", "Lokacin tsoron azzalumai.", "Addu'ar Musa (AS) lokacin da ya tashi daga Masar."),
        "dua_q_lut_unsurni" to DuaText("Dua na Lut (AS) - Taimakawa Kan Masu Cin Hanci da Rashawa", "Ya Ubangijina, Ka taimake ni a kan mutane azzalumai.", "Domin taimako a kan masu yada fasadi.", "Addu'ar masu tsayuwa akan gaskiya."),
        "dua_q_hab_li_salihin" to DuaText("Addu'ar Ibrahim (AS) Don Dan Adali", "Ubangijina, Ka ba ni (ɗa) daga salihai.", "Neman 'ya'ya salihai.", "Ta wannan dua Isma'il (AS) aka bada."),
        "dua_q_wasita_kulla_shay" to DuaText("Addu'ar Mala'iku Masu ɗauke da Al'arshi", "Ya Ubangijinmu, Kai ne Mai kewaye da komai da rahama da ilimi, don haka ka gafarta wa wanda ya tuba kuma ya bi tafarkinKa, kuma Ka tsare su daga azabar wuta.", "Mala'ikun da suke ɗauke da Al'arshi suna yin wannan addu'a ga muminai.", "Ana karantawa da niyyar a sanya a cikin addu'ar mala'iku."),
        "dua_q_ikhwanina" to DuaText("Ga Yan Uwan Mu Da Suka Gabace Mu", "Ubangijinmu! Ya Ubangijinmu, lalle ne Kai, Kai ne Mai tausayi, Mai jin ƙai.", "Addu'a ga muminai waɗanda suka zo gabaninsu da kuma tsarkakakkiyar zuciya.", "Addu'a ga Sahabbai masu daraja (RA) da muminai na farko."),
        "dua_q_alayka_tawakkalna" to DuaText("Gareka Muke Dogara (Ibrahim AS)", "Ya Ubangijinmu, gare Ka muke dõgara, zuwa gare Ka muke tuba, kuma zuwa gare Ka makõma take. Ya Ubangijinmu kada Ka sanya mu fitina ga kafirai, kuma Ka gafarta mana. Ubangijinmu, lalle ne Kai, Kai ne Mabuwayi, Mai hikima.", "Addu'ar Ibrahim (AS) da Sahabbansa.", "Addu'ar tawakkali ga Allah da komawa gare shi."),
        "dua_q_atmim_nurana" to DuaText("Cikakken Hasken Mu", "Ubangijinmu Ka kammala mana haskenmu, kuma Ka gafarta mana. Lalle ne Kai, a kan kõme, Mai ĩkon yi ne.", "Addu'ar muminai ranar kiyama.", "Neman haske akan Sirat."),
        "dua_q_asiya_baytan" to DuaText("Dua of Asiya - A House in Jannah", "Ubangijina Ka gina mini wani gida a kusa da kai a cikin Aljanna, Ka tsare ni daga Fir'auna da aikinsa, kuma Ka tsare ni daga mutane azzalumai.", "Addu'ar Asiya, matar Fir'auna.", "Allah Ya sanya ta zama abin koyi ga muminai."),
        "dua_adhan_response" to DuaText("Amsa ga Adhan", "Babu wani ƙarfi da ƙarfi face wurin Allah.", "Maimaita abin da liman ya ce; a 'Hayya 'alas-salah' da 'Hayya 'al-falah' su ce wannan.", "Duk wanda ya amsa daga zuci zai shiga Aljannah."),
        "dua_adhan_shahadah" to DuaText("Bayan Shahadar Muazin", "Kuma ni ma ina shaidawa babu abin bautawa da gaskiya sai Allah Shi kadai, ba abokin tarayya ba, kuma Muhammadu ﷺ bawanSa ne kuma ManzonSa ne. Na yarda da Allah a matsayin Ubangiji, Muhammadu ﷺ a matsayin Manzo, Musulunci addini ne.", "Da jin shedar muezzin na imani.", "An gafarta masa zunubansa."),
        "dua_istiftah_baid" to DuaText("Bude Dua: Nisantar Ni Daga Zunubai", "Ya Allah ka nisantar da ni daga zunubai na kamar yadda ka nisanta gabas da yamma. Ya Allah ka kankare min zunubai kamar yadda farar tufa ke kankare datti. Ya Allah Ka wanke min zunubaina da ruwa da dusar ƙanƙara da ƙanƙara.", "Bayan bude takbir (ana iya cewa a madadin Sana).", "Annabi ﷺ ya karanta wannan tsakanin takbir da karatun."),
        "dua_hamdan_kathiran" to DuaText("Yabo Mai Yawa Bayan Ruku'u", "Ya Ubangijinmu, Gõdiya ta tabbata a gare Ka.", "Bayan an tashi daga ruku, tare da 'Rabbana lakal-hamd'.", "Sama da mala'iku talatin ne suka yi ta tsere don zama farkon wanda ya rubuta ta."),
    )
}
